import type {
  PublicationsDebAptCreateData,
  PublicationsDebVerbatimCreateData,
} from "@app/client";

import { publicationSourceFields } from "../fragments/publication";
import { signingServiceField } from "../fragments/repository";
import { defineForm } from "../kit/defineForm";

/** A structured APT publication: dists/ and pool/ generated by Pulp, optionally signed. */
export const debAptPublicationForm = defineForm<
  PublicationsDebAptCreateData["body"]
>()(({ f, s }) => ({
  title: { create: "Create APT publication", edit: "APT publication" },
  docsUrl: "https://pulpproject.org/pulp_deb/",
  sections: [
    s.essentials([
      ...publicationSourceFields(f, { pulpTypes: ["deb.deb"] }),
      f.row([
        f.switch("structured", {
          label: "Structured",
          defaultValue: true,
          help: "Publish the upstream distributions and components as synced.",
        }),
        f.switch("simple", {
          label: "Simple",
          help: "Also publish every package in one 'default' distribution and component.",
        }),
      ]),
      signingServiceField(f, "signing_service", {
        label: "Signing service",
        help: "Signs the Release files. Empty uses the repository's signing service.",
      }),
    ]),
    s.collapsible("publishing", "Publishing", [
      f.select("layout", {
        label: "Package layout",
        defaultValue: "nested_alphabetically",
        options: [
          { value: "nested_alphabetically", label: "Nested alphabetically" },
          { value: "nested_by_digest", label: "Nested by digest" },
          { value: "nested_by_both", label: "Nested by both" },
        ],
      }),
      f.row([
        f.switch("publish_upstream_release_fields", {
          label: "Publish upstream Release fields",
        }),
        f.switch("publish_legacy_release_files", {
          label: "Publish legacy Release files",
          help: "Also publish per-component and per-architecture Release files.",
        }),
        f.switch("checkpoint", {
          label: "Checkpoint",
          help: "Keep this publication as a dated checkpoint.",
        }),
      ]),
      f.stringList("excluded_package_metadata_fields", {
        label: "Excluded metadata fields",
        help: "Custom package metadata fields to leave out of the Packages indices.",
      }),
    ]),
  ],
}));

/** A verbatim publication republishes the upstream files exactly as synced. */
export const debVerbatimPublicationForm = defineForm<
  PublicationsDebVerbatimCreateData["body"]
>()(({ f, s }) => ({
  title: {
    create: "Create verbatim APT publication",
    edit: "Verbatim APT publication",
  },
  docsUrl: "https://pulpproject.org/pulp_deb/",
  sections: [
    s.essentials(publicationSourceFields(f, { pulpTypes: ["deb.deb"] })),
  ],
}));
